import React, { useState, useEffect } from 'react';
import { Container, Row, Col, Card, Table, Badge, Button, Modal, Form } from 'react-bootstrap';
import { toast } from 'react-toastify';
import { adminAPI } from '../../services/api';

const AllBookings = () => {
  const [bookings, setBookings] = useState([]);
  const [filteredBookings, setFilteredBookings] = useState([]);
  const [zoomLinks, setZoomLinks] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('all');
  const [selectedBooking, setSelectedBooking] = useState(null);
  const [showDetailModal, setShowDetailModal] = useState(false);
  const [showApproveModal, setShowApproveModal] = useState(false);
  const [showRejectModal, setShowRejectModal] = useState(false);
  const [selectedZoomId, setSelectedZoomId] = useState('');
  const [rejectionReason, setRejectionReason] = useState('');
  const [adminNotes, setAdminNotes] = useState('');

  useEffect(() => {
    fetchData();
  }, []);

  useEffect(() => {
    filterBookings();
  }, [bookings, filter]);

  const fetchData = async () => {
    try {
      setLoading(true);
      console.log('🔍 Fetching all bookings data...');
      
      const [bookingsRes, zoomRes] = await Promise.all([
        adminAPI.getAllRequests(),
        adminAPI.getZoomLinks()
      ]);
      
      console.log('📋 Bookings response:', bookingsRes);
      console.log('🔗 Zoom links response:', zoomRes);
      
      // Handle bookings data with validation
      let bookings = [];
      if (bookingsRes.data) {
        if (Array.isArray(bookingsRes.data)) {
          bookings = bookingsRes.data;
        } else if (bookingsRes.data.data && Array.isArray(bookingsRes.data.data)) {
          bookings = bookingsRes.data.data;
        }
      }

      // Handle zoom links data with validation
      let zoomLinks = [];
      if (zoomRes.data) {
        if (Array.isArray(zoomRes.data)) {
          zoomLinks = zoomRes.data;
        } else if (zoomRes.data.data && Array.isArray(zoomRes.data.data)) {
          zoomLinks = zoomRes.data.data;
        }
      }

      // Ensure both are arrays
      if (!Array.isArray(bookings)) {
        console.warn('⚠️ Bookings is not an array, setting to empty array');
        bookings = [];
      }

      if (!Array.isArray(zoomLinks)) {
        console.warn('⚠️ Zoom links is not an array, setting to empty array');
        zoomLinks = [];
      }

      console.log('📊 Processed bookings:', bookings);
      console.log('🔗 Processed zoom links:', zoomLinks);
      
      setBookings(bookings);
      setZoomLinks(zoomLinks);
    } catch (error) {
      console.error('❌ Error fetching data:', error);
      console.error('Error details:', error.response?.data);
      
      // Set empty arrays on error
      setBookings([]);
      setZoomLinks([]);
      
      toast.error('Gagal memuat data');
    } finally {
      setLoading(false);
    }
  };

  const filterBookings = () => {
    if (filter === 'all') {
      setFilteredBookings(bookings);
    } else {
      setFilteredBookings(bookings.filter(booking => booking.status === filter));
    }
  };

  const handleApprove = (booking) => {
    setSelectedBooking(booking);
    if (booking.request_type === 'zoom' || booking.request_type === 'both') {
      setShowApproveModal(true);
    } else {
      submitApprove(booking.id, null);
    }
  };

  const handleReject = (booking) => {
    setSelectedBooking(booking);
    setShowRejectModal(true);
  };

  const submitApprove = async (bookingId, zoomLinkId) => {
    try {
      const data = zoomLinkId ? { zoom_link_id: zoomLinkId } : {};
      await adminAPI.approveRequest(bookingId, data);
      toast.success('Booking berhasil disetujui!');
      fetchData();
      setShowApproveModal(false);
      setSelectedZoomId('');
    } catch (error) {
      console.error('Error approving booking:', error);
      toast.error('Gagal menyetujui booking');
    }
  };

  const submitReject = async () => {
    if (!rejectionReason.trim()) {
      toast.error('Alasan penolakan harus diisi');
      return;
    }

    try {
      await adminAPI.rejectRequest(selectedBooking.id, {
        rejection_reason: rejectionReason
      });
      toast.success('Booking berhasil ditolak!');
      fetchData();
      setShowRejectModal(false);
      setRejectionReason('');
    } catch (error) {
      console.error('Error rejecting booking:', error);
      toast.error('Gagal menolak booking');
    }
  };

  const getStatusBadge = (status) => {
    const variants = {
      pending: 'warning',
      approved: 'success',
      rejected: 'danger'
    };
    return <Badge bg={variants[status]}>{status.toUpperCase()}</Badge>;
  };

  const getTypeBadge = (type) => {
    const variants = {
      room: 'info',
      zoom: 'primary',
      both: 'success'
    };
    const labels = {
      room: 'Ruangan',
      zoom: 'Zoom',
      both: 'Ruangan + Zoom'
    };
    return <Badge bg={variants[type]}>{labels[type]}</Badge>;
  };

  if (loading) {
    return (
      <div className="text-center py-5">
        <div className="spinner-border" role="status">
          <span className="visually-hidden">Loading...</span>
        </div>
      </div>
    );
  }

  return (
    <Container fluid>
      {/* Header */}
      <Row className="mb-4">
        <Col>
          <h2>Semua Booking</h2>
          <p className="text-muted">Kelola semua booking dari seluruh user</p>
        </Col>
      </Row>

      {/* Filter */}
      <Row className="mb-3">
        <Col>
          <Card className="border-0 shadow-sm">
            <Card.Body className="py-3">
              <Form.Group className="d-flex align-items-center mb-0">
                <Form.Label className="me-3 mb-0">Filter Status:</Form.Label>
                <Form.Select
                  value={filter}
                  onChange={(e) => setFilter(e.target.value)}
                  style={{ width: 'auto' }}
                >
                  <option value="all">Semua Status</option>
                  <option value="pending">Pending</option>
                  <option value="approved">Approved</option>
                  <option value="rejected">Rejected</option>
                </Form.Select>
              </Form.Group>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* Bookings Table */}
      <Row>
        <Col>
          <Card>
            <Card.Body>
              {filteredBookings.length > 0 ? (
                <Table responsive hover>
                  <thead>
                    <tr>
                      <th>User</th>
                      <th>Judul</th>
                      <th>Tanggal</th>
                      <th>Waktu</th>
                      <th>Jenis</th>
                      <th>Kapasitas</th>
                      <th>Status</th>
                      <th>Aksi</th>
                    </tr>
                  </thead>
                  <tbody>
                    {filteredBookings.map((booking) => (
                      <tr key={booking.id}>
                        <td>{booking.user_email}</td>
                        <td>
                          <strong>{booking.title}</strong>
                          <br />
                          <small className="text-muted">{booking.purpose}</small>
                        </td>
                        <td>{new Date(booking.date).toLocaleDateString('id-ID')}</td>
                        <td>{booking.start_time} - {booking.end_time}</td>
                        <td>{getTypeBadge(booking.request_type)}</td>
                        <td>{booking.capacity} orang</td>
                        <td>{getStatusBadge(booking.status)}</td>
                        <td>
                          <div className="btn-group">
                            <Button
                              variant="outline-info"
                              size="sm"
                              onClick={() => {
                                setSelectedBooking(booking);
                                setShowDetailModal(true);
                              }}
                            >
                              <i className="fas fa-eye"></i>
                            </Button>
                            {booking.status === 'pending' && (
                              <>
                                <Button
                                  variant="success"
                                  size="sm"
                                  onClick={() => handleApprove(booking)}
                                >
                                  <i className="fas fa-check"></i>
                                </Button>
                                <Button
                                  variant="danger"
                                  size="sm"
                                  onClick={() => handleReject(booking)}
                                >
                                  <i className="fas fa-times"></i>
                                </Button>
                              </>
                            )}
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </Table>
              ) : (
                <div className="text-center py-5">
                  <i className="fas fa-calendar-times fa-3x text-muted mb-3"></i>
                  <h5>Tidak ada booking</h5>
                  <p className="text-muted">
                    {filter === 'all' 
                      ? 'Belum ada booking yang dibuat' 
                      : `Tidak ada booking dengan status "${filter}"`
                    }
                  </p>
                </div>
              )}
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* Detail Modal */}
      <Modal show={showDetailModal} onHide={() => setShowDetailModal(false)} size="lg">
        <Modal.Header closeButton>
          <Modal.Title>Detail Booking</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          {selectedBooking && (
            <Row>
              <Col md={6}>
                <h6>Informasi User</h6>
                <Table borderless size="sm">
                  <tbody>
                    <tr>
                      <td><strong>Email:</strong></td>
                      <td>{selectedBooking.user_email}</td>
                    </tr>
                    <tr>
                      <td><strong>PIC:</strong></td>
                      <td>{selectedBooking.pic_name}</td>
                    </tr>
                    <tr>
                      <td><strong>Kontak PIC:</strong></td>
                      <td>{selectedBooking.pic_contact}</td>
                    </tr>
                  </tbody>
                </Table>
              </Col>
              <Col md={6}>
                <h6>Informasi Booking</h6>
                <Table borderless size="sm">
                  <tbody>
                    <tr>
                      <td><strong>Judul:</strong></td>
                      <td>{selectedBooking.title}</td>
                    </tr>
                    <tr>
                      <td><strong>Jenis:</strong></td>
                      <td>{getTypeBadge(selectedBooking.request_type)}</td>
                    </tr>
                    <tr>
                      <td><strong>Status:</strong></td>
                      <td>{getStatusBadge(selectedBooking.status)}</td>
                    </tr>
                  </tbody>
                </Table>
              </Col>
              <Col xs={12}>
                <hr />
                <h6>Tujuan</h6>
                <p>{selectedBooking.purpose}</p>
                
                <h6>Waktu & Tempat</h6>
                <Table borderless size="sm">
                  <tbody>
                    <tr>
                      <td><strong>Tanggal:</strong></td>
                      <td>{new Date(selectedBooking.date).toLocaleDateString('id-ID')}</td>
                    </tr>
                    <tr>
                      <td><strong>Waktu:</strong></td>
                      <td>{selectedBooking.start_time} - {selectedBooking.end_time}</td>
                    </tr>
                    <tr>
                      <td><strong>Kapasitas:</strong></td>
                      <td>{selectedBooking.capacity} orang</td>
                    </tr>
                    {selectedBooking.room_name && (
                      <tr>
                        <td><strong>Ruangan:</strong></td>
                        <td>{selectedBooking.room_name}</td>
                      </tr>
                    )}
                  </tbody>
                </Table>

                {selectedBooking.zoom_link && (
                  <>
                    <hr />
                    <h6>Informasi Zoom</h6>
                    <Table borderless size="sm">
                      <tbody>
                        <tr>
                          <td><strong>Link:</strong></td>
                          <td>
                            <a href={selectedBooking.zoom_link} target="_blank" rel="noopener noreferrer">
                              {selectedBooking.zoom_link}
                            </a>
                          </td>
                        </tr>
                        <tr>
                          <td><strong>Meeting ID:</strong></td>
                          <td>{selectedBooking.zoom_meeting_id}</td>
                        </tr>
                        <tr>
                          <td><strong>Passcode:</strong></td>
                          <td>{selectedBooking.zoom_passcode}</td>
                        </tr>
                      </tbody>
                    </Table>
                  </>
                )}

                {selectedBooking.status === 'rejected' && selectedBooking.rejection_reason && (
                  <>
                    <hr />
                    <div className="alert alert-danger">
                      <strong>Alasan Penolakan:</strong><br />
                      {selectedBooking.rejection_reason}
                    </div>
                  </>
                )}

                {/* Admin Notes Section */}
                {selectedBooking.admin_notes && (
                  <>
                    <hr />
                    <div className="alert alert-info">
                      <strong>📝 Catatan dari Admin:</strong><br />
                      {selectedBooking.admin_notes}
                    </div>
                  </>
                )}

                {selectedBooking.zoom_notes && (
                  <>
                    <hr />
                    <div className="alert alert-primary">
                      <strong>🔗 Catatan Zoom:</strong><br />
                      {selectedBooking.zoom_notes}
                    </div>
                  </>
                )}

                {selectedBooking.room_notes && (
                  <>
                    <hr />
                    <div className="alert alert-success">
                      <strong>🏢 Catatan Ruangan:</strong><br />
                      {selectedBooking.room_notes}
                    </div>
                  </>
                )}
              </Col>
            </Row>
          )}
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowDetailModal(false)}>
            Tutup
          </Button>
        </Modal.Footer>
      </Modal>

      {/* Approve Modal */}
      <Modal show={showApproveModal} onHide={() => setShowApproveModal(false)}>
        <Modal.Header closeButton>
          <Modal.Title>Setujui Booking</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          {selectedBooking && (
            <>
              <p>Anda akan menyetujui booking:</p>
              <ul>
                <li><strong>Judul:</strong> {selectedBooking.title}</li>
                <li><strong>User:</strong> {selectedBooking.user_email}</li>
                <li><strong>Tanggal:</strong> {new Date(selectedBooking.date).toLocaleDateString('id-ID')}</li>
                <li><strong>Waktu:</strong> {selectedBooking.start_time} - {selectedBooking.end_time}</li>
              </ul>

              {(selectedBooking.request_type === 'zoom' || selectedBooking.request_type === 'both') && (
                <Form.Group className="mt-3">
                  <Form.Label>Pilih Zoom Account:</Form.Label>
                  <Form.Select
                    value={selectedZoomId}
                    onChange={(e) => setSelectedZoomId(e.target.value)}
                    required
                  >
                    <option value="">-- Pilih Zoom Account --</option>
                    {zoomLinks.filter(z => z.is_active).map(zoom => (
                      <option key={zoom.id} value={zoom.id}>
                        {zoom.zoom_account_name} ({zoom.zoom_email})
                      </option>
                    ))}
                  </Form.Select>
                </Form.Group>
              )}
            </>
          )}
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowApproveModal(false)}>
            Batal
          </Button>
          <Button 
            variant="success" 
            onClick={() => submitApprove(selectedBooking?.id, selectedZoomId || null)}
            disabled={
              (selectedBooking?.request_type === 'zoom' || selectedBooking?.request_type === 'both') 
              && !selectedZoomId
            }
          >
            Setujui
          </Button>
        </Modal.Footer>
      </Modal>

      {/* Reject Modal */}
      <Modal show={showRejectModal} onHide={() => setShowRejectModal(false)}>
        <Modal.Header closeButton>
          <Modal.Title>Tolak Booking</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          {selectedBooking && (
            <>
              <p>Anda akan menolak booking:</p>
              <ul>
                <li><strong>Judul:</strong> {selectedBooking.title}</li>
                <li><strong>User:</strong> {selectedBooking.user_email}</li>
                <li><strong>Tanggal:</strong> {new Date(selectedBooking.date).toLocaleDateString('id-ID')}</li>
              </ul>

              <Form.Group className="mt-3">
                <Form.Label>Alasan Penolakan:</Form.Label>
                <Form.Control
                  as="textarea"
                  rows={3}
                  value={rejectionReason}
                  onChange={(e) => setRejectionReason(e.target.value)}
                  placeholder="Jelaskan alasan penolakan..."
                  required
                />
              </Form.Group>
            </>
          )}
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowRejectModal(false)}>
            Batal
          </Button>
          <Button variant="danger" onClick={submitReject}>
            Tolak
          </Button>
        </Modal.Footer>
      </Modal>
    </Container>
  );
};

export default AllBookings;
